(function(){
 const modal=document.getElementById('adminDetailModal'),title=document.getElementById('adminDetailTitle'),body=document.getElementById('adminDetailBody'),data=adminDetailData||{};
 const esc=v=>String(v??'-').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'}[c]));
 const openTable=(heading,rows,type='employees')=>{title.textContent=heading;if(type==='activities')body.innerHTML=rows.length?`<div class="admin-detail-table-wrap"><table class="admin-detail-table"><thead><tr><th>Waktu</th><th>Pengguna</th><th>Aksi</th><th>Perubahan</th></tr></thead><tbody>${rows.map(a=>`<tr><td>${esc(a.created_at)}</td><td>${esc(a.user?.name||'Sistem')}</td><td>${esc(a.action)}</td><td>${esc(a.description||'-')}</td></tr>`).join('')}</tbody></table></div>`:'<p class="empty">Belum ada aktivitas.</p>';else if(type==='announcements')body.innerHTML=rows.length?`<div class="admin-detail-table-wrap"><table class="admin-detail-table"><thead><tr><th>Judul</th><th>Isi</th><th>Diterbitkan</th></tr></thead><tbody>${rows.map(a=>`<tr><td>${esc(a.title)}</td><td>${esc(a.content)}</td><td>${esc(a.published_at||'Belum dipublikasikan')}</td></tr>`).join('')}</tbody></table></div>`:'<p class="empty">Belum ada pengumuman.</p>';else body.innerHTML=rows.length?`<div class="admin-detail-table-wrap"><table class="admin-detail-table"><thead><tr><th>Nama</th><th>NIP</th><th>Divisi</th><th>Telepon</th><th>Dokumen</th><th>Kontrak</th><th>Status</th></tr></thead><tbody>${rows.map(e=>`<tr><td>${esc(e.nama||e.name)}</td><td>${esc(e.nip)}</td><td>${esc(e.jabatan_divisi||e.divisi_akademik)}</td><td>${esc(e.telepon)}</td><td>${(e.documents||[]).length}</td><td>${(e.contract_histories||[]).length?'Tersedia':'Belum tersedia'}</td><td><span class="admin-status-pill ${e.status_aktif==='aktif'?'admin-status-active':'admin-status-inactive'}">${esc(e.status_aktif||e.status_akun||'Belum diisi')}</span></td></tr>`).join('')}</tbody></table></div>`:'<p class="empty">Tidak ada data.</p>';bootstrap.Modal.getOrCreateInstance(modal).show()};
 document.querySelectorAll('.admin-dashboard .panel:not(.dashboard-detail-card)').forEach(card=>{const h=card.querySelector('h5')?.textContent||'';if(!/Aktivitas Sistem|Status Data Sistem|Pengumuman Terbaru/.test(h))return;card.classList.add('overview-click');card.addEventListener('click',e=>{if(e.target.closest('a'))e.preventDefault();if(h.includes('Aktivitas'))openTable(h,data.activities||[],'activities');else if(h.includes('Pengumuman'))openTable(h,data.announcements||[],'announcements');else openTable(h,data.employees||[]);});});
})();
